/* Settings + Skill Control Plane：写操作始终先生成确定性 diff/plan，再由浏览器会话批准。 */
const Settings={category:"general",schema:null,effective:null,settingsError:"",draft:new Map(),validation:null,validateTimer:null,operation:null,operationTimer:null,pollFailures:0,pollStarted:0,skills:null,registry:null,skillsError:"",skillMode:"catalog",query:"",filter:"all",selected:"",analysis:null,analysisProgress:null,progressTimer:null,selectedActions:new Set(),plan:null,transaction:null,transactions:[],busy:"",dialogReturn:null};
const SETTING_CATEGORIES=[["general","通用","称呼、时区与 Vault"],["system","系统与运行","运行健康、组件与计划"],["engines","AI 引擎","Provider、模型与权限"],["skills","Skills","跨引擎发现、整理与纳管"],["sources","事件源","飞书、GitHub、Gmail 与股票"],["automation","自动化","心跳、日报与分流"],["notifications","通知","macOS 与飞书提醒"],["extensions","扩展","已安装 Vertical 的启停"],["advanced","高级","网络、命令与诊断"]];
const CATEGORY_ROOTS={general:["owner","timezone","quietHours","vault"],engines:["chat","llm","providers","dispatch","engine","architecture"],sources:["connectors"],automation:["heartbeat","digest","triage"],notifications:["notify"],extensions:["verticals"],advanced:["dashboard","strategy"]};
const LABELS={verticals:"扩展",owner:"Owner",timezone:"时区",quietHours:"静默时段",vault:"知识库",chat:"对话",llm:"后台 AI",providers:"Provider",dispatch:"任务派发",engine:"会话引擎",architecture:"架构权限",connectors:"事件源",heartbeat:"心跳",digest:"日报",triage:"事件分流",notify:"通知",dashboard:"Dashboard",strategy:"策略",enabled:"启用",port:"端口",listen:"监听范围",root:"目录",name:"称呼",intervalMin:"间隔（分钟）",model:"模型",effort:"思考深度",allowFullAccess:"允许完整访问",allowedRoots:"授权目录"};
const TERMINAL_SETTINGS=new Set(["committed","restored","manual-repair"]),TERMINAL_SKILLS=new Set(["committed","rolled-back","manual-repair"]);
const controlPlaneFrozen=()=>Settings.operation?.phase==="manual-repair"||Settings.transaction?.phase==="manual-repair"||Settings.transactions.some(tx=>tx.phase==="manual-repair");
async function requestJSON(url,options={}){const response=await fetch(url,options),text=await response.text();let body={};try{body=text?JSON.parse(text):{}}catch{body={message:text}}if(!response.ok){const error=new Error(body?.error?.message||body?.message||`${url} → ${response.status}`);error.status=response.status;error.code=body?.error?.code||body?.error;error.body=body;throw error}return{status:response.status,body}}
const postJSON=(url,body)=>requestJSON(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body||{})});
const pointerParts=p=>p.slice(1).split("/").map(x=>x.replaceAll("~1","/").replaceAll("~0","~"));
const valueAt=(root,p)=>pointerParts(p).reduce((value,key)=>value?.[key],root);const labelFor=p=>pointerParts(p).map(k=>LABELS[k]||k).join(" · ");
const jsonValue=v=>typeof v==="string"?v:JSON.stringify(v),randomKey=()=>`${Date.now()}-${crypto.randomUUID()}`;

TABS.settings={init(root){root.innerHTML=`<aside class="settings-sidebar"><div class="page-head compact"><div><div class="eyebrow">CONTROL PLANE</div><h1>设置</h1><p>配置与多引擎 Skill 的统一控制面</p></div></div><nav class="settings-categories" aria-label="设置分类">${SETTING_CATEGORIES.map(([id,label,desc])=>`<button type="button" data-settings-category="${id}" aria-current="false"><strong>${label}</strong><span>${desc}</span><i id="settings-count-${id}"></i></button>`).join("")}</nav></aside><div class="settings-main"><div class="settings-toolbar"><div><h2 id="settings-title">通用</h2><p id="settings-subtitle"></p></div><button class="button ghost sm" id="settings-refresh" type="button">刷新</button></div><div class="settings-scroll" id="settings-content" aria-live="polite"></div><footer class="settings-apply" id="settings-footer"><span id="settings-footer-state"></span><div><button class="button ghost sm" id="settings-discard" type="button" hidden>全部放弃</button> <button class="button primary" id="settings-review" type="button" disabled>审阅并应用</button></div></footer></div><dialog class="control-dialog" id="settings-dialog" aria-labelledby="control-dialog-title"><div id="settings-dialog-body"></div></dialog>`;$$('[data-settings-category]',root).forEach(b=>b.addEventListener("click",async()=>{Settings.category=b.dataset.settingsCategory;if(Settings.category==="skills"&&!Settings.skills)await loadSkills(false);renderSettings()}));$("#settings-refresh",root).addEventListener("click",()=>Settings.category==="skills"?loadSkills(true):loadSettings(false));$("#settings-discard",root).addEventListener("click",()=>{Settings.draft.clear();Settings.validation=null;renderSettings()});$("#settings-review",root).addEventListener("click",reviewSettings);$("#settings-dialog",root).addEventListener("close",()=>Settings.dialogReturn?.focus?.());window.addEventListener("beforeunload",e=>{if(Settings.draft.size){e.preventDefault();e.returnValue=""}});loadSettings(true)},show(){renderSettings()}};

async function loadSettings(initial){const content=$("#settings-content");if(!content)return;if(initial)content.innerHTML=stateBox("正在读取设置…","loading");Settings.settingsError="";const operationId=new URLSearchParams(location.search).get("settingsOperation"),operationUrl=operationId?`/api/settings/operations/${encodeURIComponent(operationId)}`:"/api/settings/operations/current";const[schema,effective,current]=await Promise.allSettled([requestJSON("/api/settings/schema"),requestJSON("/api/settings/effective"),requestJSON(operationUrl)]);if(schema.status==="fulfilled")Settings.schema=schema.value.body;if(effective.status==="fulfilled")Settings.effective=effective.value.body;if(current.status==="fulfilled"&&current.value.body.operation){Settings.operation=current.value.body.operation;if(!TERMINAL_SETTINGS.has(Settings.operation.phase))pollSettingsOperation()}if(!Settings.schema||!Settings.effective)Settings.settingsError="设置服务暂时不可用；运行状态仍可在「系统」查看。";if(Settings.draft.size)scheduleValidation();renderSettings()}
function renderSettings(){const root=$("#settings-root");if(!root||!$("#settings-content"))return;const meta=SETTING_CATEGORIES.find(([id])=>id===Settings.category)||SETTING_CATEGORIES[0];$("#settings-title").textContent=meta[1];$("#settings-subtitle").textContent=meta[2];$$('[data-settings-category]',root).forEach(b=>{const on=b.dataset.settingsCategory===Settings.category;b.dataset.on=on;b.setAttribute("aria-current",on?"page":"false")});if(Settings.category==="system")window.renderSystemInSettings?.($("#settings-content"));else if(Settings.category==="skills")renderSkills($("#settings-content"));else if(Settings.settingsError)$("#settings-content").innerHTML=stateBox(Settings.settingsError,"error");else{renderConfig($("#settings-content"),Settings.category);if(Settings.category==="automation")window.renderRoutinesEditor?.($("#settings-content"))}renderFooter()}
function schemaFields(){const out=[];const walk=(nodes,pointer="")=>Object.entries(nodes||{}).forEach(([key,node])=>{const path=`${pointer}/${key.replaceAll("~","~0").replaceAll("/","~1")}`;node.type==="object"?walk(node.children,path):out.push({pointer:path,...node})});walk(Settings.schema?.nodes);return out}
const categoryFields=category=>schemaFields().filter(field=>field.metadata?.editable&&(CATEGORY_ROOTS[category]||[]).includes(pointerParts(field.pointer)[0]));
function shownValue(field){const patch=Settings.draft.get(field.pointer);if(patch?.op==="set")return patch.value;if(patch?.op==="remove")return field.default;return valueAt(Settings.effective?.effective||{},field.pointer)}
function fieldId(pointer){return`setting-${btoa(unescape(encodeURIComponent(pointer))).replaceAll("=","")}`}
// 已知可枚举字段 → 下拉选项（schema 未带 enum，按 pointer 末段/正则硬编码）。免手写框、减少输错。
const SELECT_OPTIONS={listen:[["local","仅本机 (127.0.0.1)"],["all","局域网可访问 (0.0.0.0)"]],engine:[["claude","Claude Code"],["codex","Codex"],["codebuddy","CodeBuddy"],["codechat","CodeChat"]],provider:[["","跟随系统默认"],["claude","Claude Code"],["codex","Codex"],["codebuddy","CodeBuddy"]],permission:[["","跟随引擎默认"],["safe","safe（需要审批）"],["bypass","bypass（完整权限）"]],identity:[["user","用户身份"],["bot","机器人身份"]]};
const TZ_LIST=["Asia/Shanghai","Asia/Hong_Kong","Asia/Tokyo","Asia/Singapore","America/New_York","America/Los_Angeles","Europe/London","UTC"];
function dispatchDefaultProvider(){const patch=Settings.draft.get("/dispatch/defaults/provider");return String(patch?.op==="set"?patch.value:patch?.op==="remove"?"":valueAt(Settings.effective?.effective||{},"/dispatch/defaults/provider")||"")}
function dispatchDefaultModel(){const patch=Settings.draft.get("/dispatch/defaults/model");return String(patch?.op==="set"?patch.value:patch?.op==="remove"?"":valueAt(Settings.effective?.effective||{},"/dispatch/defaults/model")||"")}
function dispatchDefaultEffort(){const patch=Settings.draft.get("/dispatch/defaults/effort");return String(patch?.op==="set"?patch.value:patch?.op==="remove"?"":valueAt(Settings.effective?.effective||{},"/dispatch/defaults/effort")||"")}
function selectOptionsFor(pointer){if(pointer==="/dispatch/defaults/model"){const provider=dispatchDefaultProvider(),models=WORK_PROVIDER_CAPABILITIES[provider]?.models||[];return[["","跟随引擎默认"],...models.map(value=>[value,value])]}if(pointer==="/dispatch/defaults/effort"){const provider=dispatchDefaultProvider(),efforts=workProviderEfforts(provider,dispatchDefaultModel());return[["","跟随引擎默认"],...efforts.map(value=>[value,WORK_EFFORT_LABELS[value]||value])]}const seg=pointer.split("/").pop();return SELECT_OPTIONS[seg]||null;}
function fieldControl(field){const value=shownValue(field),pointer=esc(field.pointer),id=fieldId(field.pointer);if(field.type==="boolean")return`<label class="setting-switch"><input id="${id}" data-setting-pointer="${pointer}" type="checkbox" ${value?"checked":""}><span>${value?"已开启":"已关闭"}</span></label>`;if(field.type==="array")return`<textarea id="${id}" data-setting-pointer="${pointer}" data-setting-type="array" rows="2" spellcheck="false">${esc(JSON.stringify(value??[]))}</textarea>`;const opts=selectOptionsFor(field.pointer);if(opts&&field.type!=="number"){const cur=String(value??"");const known=opts.some(([v])=>String(v)===cur),unsupportedDispatch=/^\/dispatch\/defaults\/(?:model|effort)$/.test(field.pointer)&&!known;return`<select id="${id}" data-setting-pointer="${pointer}" data-setting-type="${field.type}">${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===cur?"selected":""}>${esc(l)}</option>`).join("")}${known?"":`<option value="${esc(cur)}" selected ${unsupportedDispatch?"disabled":""}>${esc(unsupportedDispatch?`${cur||"（未设置）"}（所选引擎或模型不支持）`:cur||"（未设置）")}</option>`}</select>`;}if(/\/timezone$/.test(field.pointer)){return`<input id="${id}" list="tz-datalist" data-setting-pointer="${pointer}" data-setting-type="${field.type}" type="text" value="${esc(value??"")}"><datalist id="tz-datalist">${TZ_LIST.map(z=>`<option value="${z}">`).join("")}</datalist>`;}const inputType=field.type==="number"?"number":/\/(?:time|start|end)$/.test(field.pointer)?"time":"text";return`<input id="${id}" data-setting-pointer="${pointer}" data-setting-type="${field.type}" type="${inputType}" value="${esc(value??"")}" ${field.metadata?.sensitive?'autocomplete="off"':""}>`}
// 分组：按配置子对象聚合，做成层级（飞书/GitHub… 各自成组）。>2 段用前两段当组，否则用第一段。
const GROUP_NAMES={lark:"飞书",github:"GitHub",gmail:"邮件（Gmail）",stock:"股票",owner:"身份",vault:"知识库",quietHours:"静默时段",providers:"Provider",dispatch:"任务派发",defaults:"派发默认值",architecture:"架构权限",heartbeat:"心跳",digest:"日报",triage:"事件分流",timezone:"时区",notify:"通知",dashboard:"Dashboard",strategy:"策略",chat:"对话",llm:"后台 AI",engine:"会话引擎"};
// 叶子字段的短标签：分组后不再重复「事件源·lark·」前缀，只显示末段人话名。
const LEAF_LABELS={skillAnalysisModel:"Skill 整理模型",enabled:"启用",pollMin:"轮询间隔（分钟）",intervalMin:"间隔（分钟）",groupPolicy:"群消息策略",maxBatch:"单次上限",time:"时间",port:"端口",listen:"监听范围",root:"目录",dir:"默认项目目录",provider:"默认引擎",permission:"默认权限",name:"称呼",model:"默认模型",effort:"默认思考深度",identity:"身份",start:"开始",end:"结束",allowFullAccess:"允许完整访问",allowedRoots:"授权目录",timezone:"时区",engine:"引擎",aheadMin:"提前量（分钟）",window:"取材窗口",checkTimes:"检查时点",watchlist:"自选标的"};
function groupKeyOf(pointer){const parts=pointerParts(pointer);return parts.length>2?parts.slice(0,2).join("/"):parts[0];}
function groupLabelOf(key){const seg=key.split("/").pop();return GROUP_NAMES[seg]||LABELS[seg]||seg;}
function leafLabelOf(pointer){const seg=pointerParts(pointer).pop();return LEAF_LABELS[seg]||LABELS[seg]||seg;}
function settingFieldHtml(field,issues,short){const dirty=Settings.draft.has(field.pointer),overridden=Settings.effective?.provenance?.[field.pointer]==="override",issue=issues.get(field.pointer);return`<article class="settings-field editable" data-dirty="${dirty}" data-risk="${field.metadata?.risk||"low"}"><div><label for="${fieldId(field.pointer)}"><h4>${esc(short?leafLabelOf(field.pointer):labelFor(field.pointer))}</h4></label><span class="settings-path mono">${esc(field.pointer)}</span><div class="setting-badges">${overridden?"<span>本机覆盖</span>":"<span>沿用默认</span>"}${dirty?"<strong>待应用</strong>":""}${field.metadata?.risk!=="low"?"<em>高风险</em>":""}</div></div><div class="settings-editor">${fieldControl(field)}<div class="setting-actions">${overridden?`<button type="button" class="button ghost sm" data-setting-remove="${esc(field.pointer)}">沿用默认值</button>`:""}${dirty?`<button type="button" class="button ghost sm" data-setting-undo="${esc(field.pointer)}">撤销</button>`:""}</div>${issue?`<p class="setting-error" role="alert">${esc(issue)}</p>`:""}</div></article>`}
// 真层级：一个配置子对象 = 一个父分组。它的「启用」字段升为分组头上的总开关，其余字段作为子项缩进嵌在下面。
function settingGroupHtml(key,fields,issues){const enableField=fields.find(f=>pointerParts(f.pointer).pop()==="enabled");const rest=fields.filter(f=>f!==enableField);if(!enableField&&fields.length===1)return settingFieldHtml(fields[0],issues,false);const on=enableField?!!shownValue(enableField):true;return`<section class="settings-group" data-enabled="${on}"><header class="settings-group-head"><div class="settings-group-title">${esc(groupLabelOf(key))}</div>${enableField?`<div class="settings-group-switch">${fieldControl(enableField)}</div>`:""}</header>${rest.length?`<div class="settings-group-body">${rest.map(f=>settingFieldHtml(f,issues,true)).join("")}</div>`:""}</section>`}
function renderConfig(content,category){if(!Settings.schema||!Settings.effective){content.innerHTML=stateBox("正在读取设置…","loading");return}const fields=categoryFields(category),issues=new Map((Settings.validation?.issues||[]).map(x=>[x.path,x.message]));const groups=new Map();for(const f of fields){const k=groupKeyOf(f.pointer);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(f)}const body=fields.length?[...groups.entries()].map(([k,fs])=>settingGroupHtml(k,fs,issues)).join(""):`<div class="settings-callout"><strong>本分类暂无可编辑字段</strong><span>内部配置只在系统诊断中展示。</span></div>`;content.innerHTML=(Settings.operation?operationBanner(Settings.operation,"settings"):"")+body;$$('[data-setting-pointer]',content).forEach(input=>input.addEventListener("change",settingChanged));$$('[data-setting-remove]',content).forEach(b=>b.addEventListener("click",()=>{Settings.draft.set(b.dataset.settingRemove,{op:"remove",path:b.dataset.settingRemove});scheduleValidation();renderSettings()}));$$('[data-setting-undo]',content).forEach(b=>b.addEventListener("click",()=>{Settings.draft.delete(b.dataset.settingUndo);scheduleValidation();renderSettings()}))}
function settingChanged(e){const input=e.currentTarget,path=input.dataset.settingPointer,type=input.dataset.settingType||(input.type==="checkbox"?"boolean":"string");let value;try{value=type==="boolean"?input.checked:type==="number"?Number(input.value):type==="array"?JSON.parse(input.value):input.value}catch{Settings.validation={valid:false,issues:[{path,message:"请输入合法 JSON 数组"}]};renderSettings();return}Settings.draft.set(path,{op:"set",path,value});if(path==="/dispatch/defaults/provider"){const capability=WORK_PROVIDER_CAPABILITIES[value],model=capability?.defaultModel||"";Settings.draft.set("/dispatch/defaults/model",{op:"set",path:"/dispatch/defaults/model",value:model});Settings.draft.set("/dispatch/defaults/effort",{op:"set",path:"/dispatch/defaults/effort",value:model?workProviderDefaultEffort(value,model):""})}else if(path==="/dispatch/defaults/model"){const provider=dispatchDefaultProvider(),efforts=workProviderEfforts(provider,value),currentEffort=dispatchDefaultEffort();Settings.draft.set("/dispatch/defaults/effort",{op:"set",path:"/dispatch/defaults/effort",value:efforts.includes(currentEffort)?currentEffort:(value?workProviderDefaultEffort(provider,value):"")})}scheduleValidation();renderSettings()}
function scheduleValidation(){clearTimeout(Settings.validateTimer);Settings.validation=Settings.draft.size?{state:"validating",issues:[]}:null;if(Settings.draft.size)Settings.validateTimer=setTimeout(validateDraft,300)}
async function validateDraft(){try{Settings.validation=(await postJSON("/api/settings/validate",{sourceDigest:Settings.effective.sourceDigest,patches:[...Settings.draft.values()]})).body}catch(error){Settings.validation={valid:false,stale:error.status===409,issues:error.body?.issues||[{path:"",message:error.message}]}}renderSettings()}
function renderFooter(){const footer=$("#settings-footer"),state=$("#settings-footer-state"),review=$("#settings-review"),discard=$("#settings-discard");if(!footer)return;footer.hidden=Settings.category==="skills"||Settings.category==="system";if(footer.hidden)return;const draftCount=Settings.draft.size,v=Settings.validation,n=v?.valid?v.normalizedPatches?.length??draftCount:draftCount,frozen=controlPlaneFrozen();discard.hidden=!draftCount;review.disabled=!n||v?.state==="validating"||v?.valid!==true||frozen||Settings.operation&&!TERMINAL_SETTINGS.has(Settings.operation.phase);state.innerHTML=frozen?"<strong>控制面已冻结</strong> · 需要先完成人工恢复":!draftCount||v?.valid&&!n?"<strong>配置已同步</strong> · 没有有效修改":v?.state==="validating"?`<strong>正在校验 ${draftCount} 项修改…</strong>`:v?.stale?"<strong>配置已被外部修改</strong> · 草稿仍保留，请刷新后重新检查":v?.valid?`<strong>${n} 项待应用</strong> · 将事务化重启 Ownward`:`<strong>${v?.issues?.length||1} 项需要处理</strong>`}
function openDialog(html,returnEl){Settings.dialogReturn=returnEl||document.activeElement;const dialog=$("#settings-dialog"),body=$("#settings-dialog-body");body.innerHTML=html;dialog.showModal();$$('[data-dialog-close]',body).forEach(b=>b.addEventListener("click",()=>dialog.close()));return body}
function reviewSettings(e){if(!Settings.validation?.valid)return;const diff=Settings.validation.redactedDiff||[],confirmations=Settings.validation.risk?.confirmations||[];const body=openDialog(`<div class="dialog-head"><div><div class="eyebrow">HUMAN APPROVAL</div><h2 id="control-dialog-title">审阅 ${diff.length} 项配置变更</h2></div><button class="button ghost" data-dialog-close>关闭</button></div><div class="approval-effects">${diff.map(item=>`<article><strong>${esc(labelFor(item.path))}</strong><code>${esc(jsonValue(item.before))}</code><span>→</span><code>${esc(jsonValue(item.after))}</code><small>${esc(item.path)} · ${item.risk}</small></article>`).join("")}</div>${confirmations.length?`<div class="approval-confirmations">${confirmations.map(item=>`<label><input type="checkbox" data-confirmation="${esc(item)}"> 我理解并确认：${esc(item)}</label>`).join("")}</div>`:""}<div class="dialog-actions"><button class="button ghost" data-dialog-close>取消</button><button class="button primary" id="settings-approve-apply">批准并重启 Ownward</button></div>`,e?.currentTarget);$("#settings-approve-apply",body).addEventListener("click",()=>applySettings(confirmations,body))}
async function applySettings(confirmations,body){const button=$("#settings-approve-apply",body),checked=$$('[data-confirmation]:checked',body).map(x=>x.dataset.confirmation);if(confirmations.some(item=>!checked.includes(item))){toast("请逐项确认高风险影响");return}button.disabled=true;button.textContent="正在创建审批…";const payload={sourceDigest:Settings.effective.sourceDigest,patches:[...Settings.draft.values()],confirmations:checked};try{const approval=(await postJSON("/api/settings/approve",payload)).body;button.textContent="正在启动事务…";const result=(await postJSON("/api/settings/apply",{...payload,approvalId:approval.approvalId,idempotencyKey:randomKey()})).body;Settings.operation=result.operation;$("#settings-dialog").close();history.replaceState(null,"",`${location.pathname}?tab=settings&settingsOperation=${encodeURIComponent(Settings.operation.id)}`);pollSettingsOperation();renderSettings()}catch(error){button.disabled=false;button.textContent="批准并重启 Ownward";toast(`${error.code||"应用失败"}：${error.message}`)}}
function operationBanner(operation,domain){const terminal=domain==="settings"?TERMINAL_SETTINGS:TERMINAL_SKILLS,bad=["manual-repair","restored","rolled-back"].includes(operation.phase);return`<div class="operation-banner" data-state="${bad?"error":terminal.has(operation.phase)?"done":"running"}" role="${bad?"alert":"status"}"><strong>${domain==="settings"?"设置事务":"Skill 事务"} · ${esc(operation.phase)}</strong><span>${operation.error?.message?esc(operation.error.message):operation.errorCode?esc(operation.errorCode):terminal.has(operation.phase)?"事务已结束":"正在执行或恢复，请稍候"}</span><code>${esc(operation.id)}</code></div>`}
function pollSettingsOperation(){clearTimeout(Settings.operationTimer);if(!Settings.operation||TERMINAL_SETTINGS.has(Settings.operation.phase))return;if(!Settings.pollStarted)Settings.pollStarted=Date.now();Settings.operationTimer=setTimeout(async()=>{const path=`/api/settings/operations/${Settings.operation.id}`;try{Settings.operation=(await requestJSON(path)).body.operation;Settings.pollFailures=0}catch{Settings.pollFailures++;const candidate=Settings.operation.origins?.candidate;if(Settings.pollFailures>=5&&candidate&&candidate!==location.origin){location.assign(`${candidate}/?tab=settings&settingsOperation=${encodeURIComponent(Settings.operation.id)}`);return}if(Date.now()-Settings.pollStarted>180000){Settings.operation={...Settings.operation,error:{message:"无法连接旧或候选地址。请检查端口、代理与 TLS 后重新打开 Settings。"}};renderSettings();return}}if(Settings.operation?.phase==="committed"){Settings.draft.clear();Settings.validation=null;Settings.pollStarted=0;await loadSettings(false)}renderSettings();pollSettingsOperation()},1200)}

async function loadSkills(scan){Settings.skillsError="";Settings.busy=scan?"scanning":Settings.busy;if(scan)renderSettings()
  // 操作记录和恢复入口不能挂在扫描成功上：扫描失败（daemon 重启中、某个根读不了、预算耗尽）
  // 恰恰是用户最需要回滚的时候，这时候把恢复入口一起藏掉是最坏的时机。两边各自独立取。
  const history=Promise.all([requestJSON("/api/skills/transactions").catch(()=>({body:[]})),requestJSON("/api/skills/registry").catch(()=>({body:{skills:[]}}))])
  try{Settings.skills=(await(scan?postJSON("/api/skills/scan",{}):requestJSON("/api/skills"))).body}catch(error){Settings.skillsError=error.code==="SKILL_SCAN_REQUIRED"||error.status===404?"尚未扫描 Skill":`Skill inventory 暂时不可用：${error.message}`}
  const[tx,registry]=await history
  Settings.transactions=Array.isArray(tx.body)?tx.body:tx.body.transactions||[]
  Settings.registry=registry.body
  Settings.busy=""
  renderSettings()}
function skillCatalog(){let catalog;if(Array.isArray(Settings.skills?.catalog))catalog=Settings.skills?.catalog.map(item=>({...item}));else{const groups=new Map();for(const item of Settings.skills?.observations||[]){const group=groups.get(item.name)||{logicalId:item.name,name:item.name,description:item.description,observationIds:[],engines:[],scopes:[],findings:[]};group.observationIds.push(item.id);if(!group.engines.includes(item.engine))group.engines.push(item.engine);if(!group.scopes.includes(item.scope))group.scopes.push(item.scope);for(const finding of item.findings||[])if(!group.findings.includes(finding))group.findings.push(finding);groups.set(item.name,group)}catalog=[...groups.values()]}for(const managed of Settings.registry?.skills||[]){const existing=catalog.find(item=>item.name===managed.name&&item.digest===managed.digest);if(existing){existing.managedSkillId=managed.id;continue}catalog.push({logicalId:`managed:${managed.id}`,managedSkillId:managed.id,name:managed.name,description:managed.description,digest:managed.digest,ownership:"managed",observationIds:[],engines:[...new Set(managed.deployments.map(item=>item.engine))],scopes:[...new Set(managed.deployments.map(item=>item.scope))],findings:["broken"]})}return catalog.sort((a,b)=>a.name.localeCompare(b.name))}
