function skillHistoryHtml(){return`<div class="transaction-list">${Settings.transactions.length?Settings.transactions.map(tx=>`<article><div><strong>${esc(tx.phase)}</strong><code>${esc(tx.id)}</code><span>${esc(tx.updatedAt||tx.createdAt||"")}</span>${tx.errorCode?`<span class="tag warning">${esc(tx.errorCode)}</span>`:""}</div>${tx.phase==="committed"&&!controlPlaneFrozen()?`<button class="button secondary sm" data-rollback-tx="${esc(tx.id)}">审阅恢复方案</button>`:""}</article>`).join(""):stateBox("尚无 Skill 写操作记录")}</div>`}
function bindSkillControls(content){$("#skills-search",content)?.addEventListener("change",e=>{Settings.query=e.target.value;renderSettings()});if($("#skills-filter",content))$("#skills-filter",content).value=Settings.filter;$("#skills-filter",content)?.addEventListener("change",e=>{Settings.filter=e.target.value;renderSettings()});$("#skills-scan",content)?.addEventListener("click",()=>loadSkills(true));$$('[data-skill-id]',content).forEach(b=>b.addEventListener("click",()=>{Settings.selected=b.dataset.skillId;renderSettings()}));const enginesOf=b=>(b.dataset.expose||"").split(",").filter(Boolean);
  $$('[data-adopt-catalog]',content).forEach(b=>b.addEventListener("click",async()=>{const item=skillCatalog().find(item=>item.logicalId===b.dataset.adoptCatalog);if(!item){Settings.skillsError="所选 Skill 已变化，请重新扫描";renderSettings();return}const engines=enginesOf(b);const expose=engines.length?await resolveExpose(engines,{},b):[];if(expose===null)return;buildSkillPlan([{kind:"adopt",observationIds:item.observationIds,...(expose.length?{expose}:{})}],b)}));
  // 冲突选边：只纳管选中的那一版，并部署到其它引擎——目标根取另一侧现在所在的根，planner 对已存在路径走 replace-with-link（先备份）
  $$('[data-adopt-one]',content).forEach(b=>b.addEventListener("click",async()=>{const engines=enginesOf(b),hints={};for(const o of Settings.skills?.observations||[])if(engines.includes(o.engine)&&o.name===proposalObs(b.dataset.adoptOne)?.name&&o.id!==b.dataset.adoptOne)hints[o.engine]=o.displayPath||o.entryPath;const expose=engines.length?await resolveExpose(engines,hints,b):[];if(expose===null)return;buildSkillPlan([{kind:"adopt",observationIds:[b.dataset.adoptOne],...(expose.length?{expose}:{})}],b)}));
  $$('[data-conflict-diff]',content).forEach(b=>b.addEventListener("click",()=>showConflictDiff(b.dataset.conflictDiff.split(","),b)));$$('[data-delete-observation]',content).forEach(b=>b.addEventListener("click",()=>buildSkillPlan([{kind:"delete",observationId:b.dataset.deleteObservation}],b)));$$('[data-expose-skill]',content).forEach(b=>b.addEventListener("click",()=>chooseSkillRoot({kind:"migrate",skillId:b.dataset.exposeSkill,engine:b.dataset.engine,scope:"user",removeSource:false},b.dataset.rootId,b)));$$('[data-repair-skill]',content).forEach(b=>b.addEventListener("click",()=>chooseSkillRoot({kind:"repair",skillId:b.dataset.repairSkill,engine:b.dataset.engine,scope:"user"},b.dataset.rootId,b)));$$('[data-migrate-source]',content).forEach(b=>b.addEventListener("click",()=>chooseSkillRoot({kind:"migrate",skillId:b.dataset.skillId,fromObservationId:b.dataset.migrateSource,engine:b.dataset.engine,scope:"user",removeSource:true},b.dataset.rootId,b)));$$('[data-content-conflict]',content).forEach(b=>b.addEventListener("click",()=>reviewConflictContent(b.dataset.contentConflict,b)));$("#skills-analyze-rules",content)?.addEventListener("click",()=>runSkillAnalysis([],undefined,"rules"));$("#skills-analyze",content)?.addEventListener("click",()=>runSkillAnalysis([],undefined,"agent"));$("#skills-select-all",content)?.addEventListener("click",()=>{(Settings.analysis?.actions||[]).forEach((_,i)=>Settings.selectedActions.add(i));renderSettings()});
  $("#skills-select-none",content)?.addEventListener("click",()=>{Settings.selectedActions.clear();renderSettings()});
  $$('[data-proposal-index]',content).forEach(x=>x.addEventListener("change",()=>{const i=+x.dataset.proposalIndex;x.checked?Settings.selectedActions.add(i):Settings.selectedActions.delete(i);renderSettings()}));$("#skills-build-plan",content)?.addEventListener("click",()=>buildSkillPlan([...Settings.selectedActions].map(i=>Settings.analysis.actions[i]),$("#skills-build-plan",content)));$$('[data-rollback-tx]',content).forEach(b=>b.addEventListener("click",()=>reviewRollback(b.dataset.rollbackTx,b)))}
function chooseSkillRoot(action,rootId,returnEl){if(rootId){buildSkillPlan([{...action,targetRootId:rootId}],returnEl);return}const roots=engineRoots(action.engine),body=openDialog(`<div class="dialog-head"><div><div class="eyebrow">EXPLICIT ROOT</div><h2 id="control-dialog-title">选择 ${esc(action.engine)} Skill 目录</h2></div><button class="button ghost" data-dialog-close>关闭</button></div><div class="proposal-list">${roots.map(root=>`<button class="skill-root-choice" data-root-choice="${esc(root.id)}"><strong>${esc(root.path)}</strong><span>${esc(root.capabilityReason||"已声明兼容")}</span></button>`).join("")}</div>`,returnEl);$$('[data-root-choice]',body).forEach(button=>button.addEventListener("click",()=>{$("#settings-dialog").close();buildSkillPlan([{...action,targetRootId:button.dataset.rootChoice}],returnEl)}))}
async function reviewConflictContent(id,returnEl){try{const group=(Settings.skills.observations||[]).filter(obs=>obs.name===(Settings.skills.observations||[]).find(item=>item.id===id)?.name&&(obs.findings||[]).includes("conflict")).map(obs=>obs.id),result=(await postJSON("/api/skills/analysis/preview",{expectedRevision:Settings.skills.mutableRevision,contentObservationIds:group})).body,body=openDialog(`<div class="dialog-head"><div><div class="eyebrow">CONTENT OPT-IN</div><h2 id="control-dialog-title">允许比较 ${result.previews.length} 个冲突版本</h2></div><button class="button ghost" data-dialog-close>关闭</button></div>${result.previews.map(preview=>`<div class="settings-callout warning"><strong>版本 ${esc(preview.observationId.slice(0,8))}</strong><span>${preview.files.length} 个文本文件、${preview.bytes} 字节；排除 ${preview.excluded} 个脚本、附件、隐藏或二进制条目。</span></div><ul>${preview.files.map(file=>`<li><code>${esc(file.pathAlias)}</code> · ${file.bytes} bytes</li>`).join("")}</ul>`).join("")}<p>授权仅本次有效；HOME 与疑似密钥会脱敏。</p><div class="dialog-actions"><button class="button ghost" data-dialog-close>取消</button><button class="button primary" id="skills-content-confirm">允许并分析这些版本</button></div>`,returnEl);$("#skills-content-confirm",body).addEventListener("click",()=>{$("#settings-dialog").close();runSkillAnalysis(group,result.consentId,"agent")})}catch(error){toast(`${error.code||"预览失败"}：${error.message}`)}}
async function runSkillAnalysis(contentObservationIds=[],consentId,mode="rules"){Settings.busy="analysis";Settings.analysisProgress=null;renderSettings();clearInterval(Settings.progressTimer);if(mode==="agent")Settings.progressTimer=setInterval(pollAnalysisProgress,1000);try{Settings.analysis=(await postJSON("/api/skills/analysis",{expectedRevision:Settings.skills.mutableRevision,contentObservationIds,mode,...(consentId?{consentId}:{})})).body;Settings.selectedActions=new Set((Settings.analysis.actions||[]).map((_,i)=>i))}catch(error){toast(`${error.code||"分析失败"}：${error.message}`)}clearInterval(Settings.progressTimer);Settings.progressTimer=null;Settings.analysisProgress=null;Settings.busy="";renderSettings()}
async function buildSkillPlan(actions,returnEl){Settings.skillsError="";Settings.busy="planning";renderSettings();let nextPlan=null;try{nextPlan=(await postJSON("/api/skills/plan",{expectedRevision:Settings.skills.mutableRevision,actions})).body;Settings.plan=nextPlan}catch(error){Settings.skillsError=`${error.code||"计划失败"}：${error.message}`;toast(Settings.skillsError)}Settings.busy="";renderSettings();if(nextPlan)reviewSkillPlan(returnEl)}
function reviewSkillPlan(returnEl){const plan=Settings.plan,body=openDialog(`<div class="dialog-head"><div><div class="eyebrow">FILESYSTEM PLAN</div><h2 id="control-dialog-title">审阅 ${plan.effects.length} 项 Skill 操作</h2></div><button class="button ghost" data-dialog-close>关闭</button></div><div class="approval-effects">${plan.effects.map(effect=>`<article data-danger="${effect.destructive}"><strong>${esc(effect.summary)}</strong><code>${esc(effect.path)}</code><small>${esc(effect.kind)}${effect.destructive?" · 将替换、移动或删除现有条目":" · 仅创建新条目"}</small></article>`).join("")}</div><div class="settings-callout warning"><strong>备份与回滚</strong><span>现有条目先进入 ~/.ownward/skills/backups；失败按相反顺序恢复。</span></div><div class="dialog-actions"><button class="button ghost" data-dialog-close>取消</button><button class="button primary" id="skills-approve-apply">批准并执行 ${plan.effects.length} 项操作</button></div>`,returnEl);$("#skills-approve-apply",body).addEventListener("click",()=>applySkillPlan(body))}
async function applySkillPlan(body){const button=$("#skills-approve-apply",body);button.disabled=true;button.textContent="正在执行…";Settings.skillsError="";try{const approval=(await postJSON(`/api/skills/plans/${encodeURIComponent(Settings.plan.id)}/approval`,{expectedPlanDigest:Settings.plan.digest})).body;Settings.transaction=(await postJSON("/api/skills/apply",{planId:Settings.plan.id,expectedPlanDigest:Settings.plan.digest,expectedRevision:Settings.skills.mutableRevision,idempotencyKey:randomKey(),approval:{id:approval.id,nonce:approval.nonce}})).body;$("#settings-dialog").close();await loadSkills(true);Settings.analysis=null;Settings.selectedActions.clear();Settings.plan=null;Settings.skillMode="history"}catch(error){if(error.code==="SKILL_TRANSACTION_CONFLICT"){Settings.plan=null;$("#settings-dialog").close();Settings.skillsError="这个方案上一次执行失败并已自动回滚（错误码见「操作记录」），同一方案不能重复提交。请重新点「审阅」生成新方案。";toast(Settings.skillsError);renderSettings();return}button.disabled=false;button.textContent=`批准并执行 ${Settings.plan.effects.length} 项操作`;Settings.skillsError=`${error.code||"执行失败"}：${error.message}`;toast(Settings.skillsError)}renderSettings()}
// 恢复前必须拿**服务端当前**的清单，不能信页面缓存：daemon 重启后 GET /api/skills 是 404
// （SKILL_SCAN_REQUIRED），页面的 Settings.skills 就是 null——而操作记录现在不依赖扫描也能打开，
// 于是 Settings.skills.mutableRevision 直接空指针（2026-09-03 实测）。审批把 revision 烧进摘要，
// 门比的是服务端此刻的快照，所以本来就该现取。
async function currentInventory(){try{return(await requestJSON("/api/skills")).body}catch(error){if(error.status===404||error.code==="SKILL_SCAN_REQUIRED")return(await postJSON("/api/skills/scan",{})).body;throw error}}
// 冲突两侧逐文件差异：给用户看清「只是路径不同」还是真的两个版本，再决定以哪一版为准。
// 部署到别的引擎时定目标根：给了现有部署路径就用它所在的根（原地换成链接）；否则根唯一就直用；
// 多个根（codex 有 ~/.agents/skills 和 ~/.codex/skills）就逐个弹选择。planner 对多根要求显式 targetRootId。
async function resolveExpose(engines,hintPathByEngine={},returnEl){const out=[];for(const engine of engines){let rootId=targetRootId(engine,hintPathByEngine[engine]);if(!rootId){const roots=engineRoots(engine);if(roots.length===1)rootId=roots[0].id;else rootId=await new Promise(resolve=>{const body=openDialog(`<div class="dialog-head"><div><div class="eyebrow">EXPLICIT ROOT</div><h2 id="control-dialog-title">部署到 ${esc(engine)}：选择目录</h2></div><button class="button ghost" data-dialog-close>关闭</button></div><div class="proposal-list">${roots.map(root=>`<button class="skill-root-choice" data-root-choice="${esc(root.id)}"><strong>${esc(root.path)}</strong><span>${esc(root.capabilityReason||"已声明兼容")}</span></button>`).join("")}</div>`,returnEl);$$('[data-root-choice]',body).forEach(b=>b.addEventListener("click",()=>{$("#settings-dialog").close();resolve(b.dataset.rootChoice)}));$("#settings-dialog").addEventListener("close",()=>resolve(""),{once:true})})}if(!rootId)return null;out.push({engine,scope:"user",targetRootId:rootId})}return out}
// 冲突组里能「选为准」的一侧：discovered、健康、不是技能包（整包纳管会被 planner 拒）
function conflictSides(ids){return(Settings.skills?.observations||[]).filter(o=>ids.includes(o.id)&&(o.findings||[]).includes("conflict")&&o.ownership==="discovered"&&!(o.nestedSkills>0)&&!['bounded','unreadable','malformed','broken','empty'].includes(o.state))}
async function showConflictDiff(ids,returnEl){const sides=conflictSides(ids).slice(0,2);const item={name:sides[0]?.name||"?"};if(sides.length!==2){toast("差异比较需要恰好两个冲突项");return}
  try{const d=(await postJSON("/api/skills/conflict-diff",{expectedRevision:Settings.skills.mutableRevision,observationIds:sides.map(o=>o.id)})).body;
    const label=o=>`${o.engine} · ${o.displayPath||o.entryPath}`,changed=d.files.filter(f=>f.status!=="same"),same=d.files.length-changed.length;
    const rows=changed.map(f=>f.status==="different"?`<details open><summary><code>${esc(f.path)}</code> · ${f.lines.length}${f.truncated?"+":""} 行不同</summary><table class="diff-table"><tbody>${f.lines.map(l=>`<tr><td>${l.n}</td><td>${esc(l.left??"（无）")}</td><td>${esc(l.right??"（无）")}</td></tr>`).join("")}</tbody></table></details>`:`<div><code>${esc(f.path)}</code> · ${f.status==="only-left"?"只在左侧":"只在右侧"}</div>`).join("");
    openDialog(`<div class="dialog-head"><div><div class="eyebrow">CONFLICT</div><h2 id="control-dialog-title">${esc(item.name)} 两侧差异</h2></div><button class="button ghost" data-dialog-close>关闭</button></div><p class="diff-legend"><span>左：${esc(label(sides[0]))}</span><span>右：${esc(label(sides[1]))}</span></p><p>${same} 个文件相同，${changed.length} 个不同。选一版为准后，另一侧的目录会先备份、再换成指向受管副本的链接。</p><div class="diff-files">${rows||"<div>可比较的文本文件没有差异（差异可能在脚本、附件或被裁剪的部分）</div>"}</div><div class="dialog-actions">${sides.map((o,i)=>`<button class="button ${i?"secondary":"primary"}" data-diff-pick="${esc(o.id)}" data-expose="${esc(sides.filter(x=>x!==o).map(x=>x.engine).join(","))}">以${i?"右":"左"}侧（${esc(o.engine)}）为准…</button>`).join("")}</div>`,returnEl);
    $$('[data-diff-pick]',$("#settings-dialog-body")).forEach(b=>b.addEventListener("click",async()=>{const engines=(b.dataset.expose||"").split(",").filter(Boolean),hints={};for(const o of sides)if(o.id!==b.dataset.diffPick)hints[o.engine]=o.displayPath||o.entryPath;$("#settings-dialog").close();const expose=engines.length?await resolveExpose(engines,hints,returnEl):[];if(expose===null)return;buildSkillPlan([{kind:"adopt",observationIds:[b.dataset.diffPick],...(expose.length?{expose}:{})}],returnEl)}));
  }catch(error){toast(`${error.code||"差异比较失败"}：${error.message}`)}}
async function reviewRollback(id,returnEl){try{const preview=(await requestJSON(`/api/skills/transactions/${encodeURIComponent(id)}/rollback-plan`)).body,body=openDialog(`<div class="dialog-head"><div><div class="eyebrow">CONDITIONAL ROLLBACK</div><h2 id="control-dialog-title">恢复 Skill 事务</h2></div><button class="button ghost" data-dialog-close>关闭</button></div><div class="approval-effects">${preview.effects.map(effect=>`<article data-danger="true"><strong>${esc(effect.summary)}</strong><code>${esc(effect.path)}</code><small>${esc(effect.action)}</small></article>`).join("")}</div><div class="settings-callout warning"><strong>仅在上述后置条件仍匹配时恢复</strong><span>如果路径已被后来事务或人工修改，Ownward 会拒绝覆盖，并要求根据当前状态生成新的逆向方案。</span></div><div class="dialog-actions"><button class="button ghost" data-dialog-close>取消</button><button class="button primary" id="skills-confirm-rollback">批准执行 ${preview.effects.length} 项恢复操作</button></div>`,returnEl);$("#skills-confirm-rollback",body).addEventListener("click",async()=>{try{const inventory=await currentInventory();Settings.skills=inventory;const approval=(await postJSON(`/api/skills/transactions/${encodeURIComponent(id)}/rollback/approval`,{expectedRevision:inventory.mutableRevision})).body;Settings.transaction=(await postJSON(`/api/skills/transactions/${encodeURIComponent(id)}/rollback`,{expectedRevision:inventory.mutableRevision,approval:{id:approval.id,nonce:approval.nonce}})).body;$("#settings-dialog").close();await loadSkills(true)}catch(error){toast(`${error.code||"恢复失败"}：${error.message}`)}renderSettings()})}catch(error){toast(`${error.code||"恢复方案不可用"}：${error.message}`)}}

/** 日报/周报规则编辑器（追加到「自动化」分类）：结构化编辑 routine 的启用/时间/取材窗口/星期，写回 routines.json。 */
window.renderRoutinesEditor = async function (content) {
  if (!content) return;
  const wrap = document.createElement("section");
  wrap.className = "settings-group";
  wrap.innerHTML = `<div class="settings-group-title">日报 / 周报 / 月度复盘</div><div id="routines-rules">${stateBox("加载中…", "loading")}</div>`;
  content.appendChild(wrap);
  const rules = await getJSON("/api/routines/rules").catch(() => null);
  const el = wrap.querySelector("#routines-rules");
  if (!rules) { el.innerHTML = stateBox("无法载入 routine 规则", "error"); return; }
  if (!Array.isArray(rules) || !rules.length) { el.innerHTML = `<div class="settings-callout"><span>暂无周期职责。样例见 examples/routines.json。</span></div>`; return; }
  const WD = ["日", "一", "二", "三", "四", "五", "六"];
  el.innerHTML = rules.map((r) => `<article class="settings-field editable" data-routine="${esc(r.id)}">
    <div><label><h4>${esc(r.name || r.id)}</h4></label>${r.docUrl ? `<a class="settings-path mono" href="${esc(r.docUrl)}" target="_blank" rel="noopener">飞书文档 ↗</a>` : `<span class="settings-path mono">${esc(r.id)}</span>`}</div>
    <div class="settings-editor routine-editor">
      <label class="setting-switch"><input type="checkbox" data-rk="enabled" ${r.enabled ? "checked" : ""}><span>${r.enabled ? "已启用" : "已停用"}</span></label>
      <div class="routine-row"><label class="routine-inline">时间 <input type="time" data-rk="time" value="${esc(r.time || "")}"></label>
      <label class="routine-inline">取材 <select data-rk="window"><option value="yesterday" ${r.window === "yesterday" ? "selected" : ""}>上一个工作日</option><option value="week" ${r.window === "week" ? "selected" : ""}>本周</option><option value="month" ${r.window === "month" ? "selected" : ""}>上个自然月</option></select></label></div>
      <label class="routine-inline">周期 <select data-rk="cadence"><option value="weekly" ${r.cadence !== "monthly" ? "selected" : ""}>按星期</option><option value="monthly" ${r.cadence === "monthly" ? "selected" : ""}>每月首个周一前的周日</option></select></label>
      <div class="routine-days"><span>星期（按星期时生效）</span>${WD.map((w, i) => `<label class="routine-day"><input type="checkbox" data-rk="day" value="${i}" ${(r.days || []).includes(i) ? "checked" : ""}>${w}</label>`).join("")}</div>
      <label>覆盖人员（逗号分隔，留空使用本人姓名）<input type="text" data-rk="people" value="${esc((r.people || []).join("，"))}"></label>
      <label>会议材料来源（选择已有职责的文档）<select multiple data-rk="refRoutines" aria-label="会议材料来源">${rules.filter((ref) => ref.id !== r.id).map((ref) => `<option value="${esc(ref.id)}" ${(r.refRoutines || []).includes(ref.id) ? "selected" : ""}>${esc(ref.name || ref.id)}</option>`).join("")}</select></label>
      <div><button class="button primary sm" data-routine-save="${esc(r.id)}">保存规则</button>${r.refRoutines?.length ? ` <button class="button secondary sm" data-routine-archive="${esc(r.id)}">刷新会议归档</button> <button class="button ghost sm" data-routine-archive-status="${esc(r.id)}">查看归档状态</button>` : ""}</div>
      <p data-archive-result role="status"></p>
    </div></article>`).join("");
  el.querySelectorAll("[data-routine-save]").forEach((b) => b.addEventListener("click", async () => {
    const art = b.closest("[data-routine]"), id = b.dataset.routineSave;
    const patch = {
      enabled: art.querySelector('[data-rk="enabled"]').checked,
      time: art.querySelector('[data-rk="time"]').value,
      window: art.querySelector('[data-rk="window"]').value,
      cadence: art.querySelector('[data-rk="cadence"]').value,
      people: art.querySelector('[data-rk="people"]').value.split(/[,，\n]/).map((x) => x.trim()).filter(Boolean),
      refRoutines: [...art.querySelector('[data-rk="refRoutines"]').selectedOptions].map((x) => x.value),
      days: [...art.querySelectorAll('[data-rk="day"]:checked')].map((x) => +x.value),
    };
    b.disabled = true;
    try {
      const res = await post("/api/routines/rules", { id, patch });
      toast(res.msg || (res.ok ? "已保存" : "失败"));
    } catch { toast("保存失败，请重试"); }
    finally { b.disabled = false; }
  }));
  el.querySelectorAll("[data-routine-archive]").forEach((b) => b.addEventListener("click", async () => {
    b.disabled = true;
    try { const res = await post("/api/routines/archive", { id: b.dataset.routineArchive }); b.closest("[data-routine]").querySelector("[data-archive-result]").textContent = res.ok ? `已归档 ${res.sources.length} 个来源。可在今日页单独生成月报。` : (res.msg || "归档失败，已保存的旧版本保留"); toast(res.msg || (res.ok ? "会议材料已归档" : "归档失败")); }
    catch { toast("归档失败，请重试"); }
    finally { b.disabled = false; }
  }));
  el.querySelectorAll("[data-routine-archive-status]").forEach((b) => b.addEventListener("click", async () => {
    b.disabled = true;
    const result = b.closest("[data-routine]").querySelector("[data-archive-result]");
    try {
      const res = await getJSON(`/api/routines/archive?id=${encodeURIComponent(b.dataset.routineArchiveStatus)}`);
      result.textContent = res?.ok ? (res.sources.map((s) => `${s.name}：${s.status === "ready" ? `已归档 ${s.fetchedAt} · ${s.hash.slice(0, 12)}` : "尚无可用归档，请刷新"}`).join("；") || "没有配置会议来源") : (res?.msg || "读取状态失败");
    } catch { result.textContent = "读取状态失败，请重试"; }
    finally { b.disabled = false; }
  }));
};

/** 从任意 tab 跳到对应设置分类（tab↔设置联动）。 */
window.openSettings = function (category) {
  if (category) Settings.category = category;
  switchTab("settings");
  if (category) setTimeout(() => { if (typeof renderSettings === "function") renderSettings(); }, 0);
};
